insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('f8d8bwnmba', 'daily:wuerzburg-dom:1610-michael-kern-the-younger-pulpit-of-w-rzburg-cathedral', 'Pulpit of Würzburg Cathedral', 'Michael Kern the Younger', 1610, '1609–1610', null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/1609_bis_1610_schuf_Michael_Kern_der_J%C3%BCngere_die_Kanzel_in_St._Kilian_W%C3%BCrzburg._01.jpg/1280px-1609_bis_1610_schuf_Michael_Kern_der_J%C3%BCngere_die_Kanzel_in_St._Kilian_W%C3%BCrzburg._01.jpg', 'Michael Kern the Younger carved this pulpit in 1609 and 1610. For centuries the sermon came from up here, above the heads of the congregation.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('unmv9rqja6', 'daily:wuerzburg-dom:1981-andreas-moritz-menorah', 'Menorah', 'Andreas Moritz', 1981, null, null, 'metal', 'Würzburg Cathedral (Kiliansdom)', 3, 'object', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Menorah_-_St._Kilian%27s_Cathedral_-_W%C3%BCrzburg_-_Germany_2017.jpg/1280px-Menorah_-_St._Kilian%27s_Cathedral_-_W%C3%BCrzburg_-_Germany_2017.jpg', 'The seven-branched candelabrum stands in the middle of the nave. Andreas Moritz made it in 1981, more than ten years after the rebuilt cathedral reopened.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('2hat3rgzjg', 'daily:wuerzburg-dom:1499-tilman-riemenschneider-tomb-of-prince-bishop-rudolf-von-scheren', 'Tomb of Prince-Bishop Rudolf von Scherenberg', 'Tilman Riemenschneider', 1499, '1496–1499', null, 'marble', 'Würzburg Cathedral (Kiliansdom)', 2, 'sculpture', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Das_Epitaph_des_Rudolf_von_Scherenberg_im_Kiliansdom._01.jpg/1280px-Das_Epitaph_des_Rudolf_von_Scherenberg_im_Kiliansdom._01.jpg', 'Rudolf von Scherenberg died in 1495, and Riemenschneider got the commission a year later. The marble monument went up in 1499 and shows the bishop as a very old man, wrinkles and all.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('38up9vv29h', 'daily:wuerzburg-dom:1623-michael-kern-attributed-tomb-of-jakob-baur-von-eiseneck', 'Tomb of Jakob Baur von Eiseneck', 'Michael Kern (attributed)', 1623, '1623, attributed to Michael Kern', null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Jakob_Baur_von_Eiseneck_15.09.2024_001.jpg/1280px-Jakob_Baur_von_Eiseneck_15.09.2024_001.jpg', 'Jakob Baur von Eiseneck was a colonel in the prince-bishop''s service. He died in July 1621 near Rozvadov in Bohemia, early in the Thirty Years'' War, and his tomb followed in 1623.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('d8dw8kcehs', 'daily:wuerzburg-dom:1279-master-eckart-of-worms-baptismal-font', 'Baptismal font', 'Master Eckart of Worms', 1279, null, null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'object', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/1279_schuf_Meister_Eckkart_aus_Worms_diesen_Taufstein._01.jpg/1280px-1279_schuf_Meister_Eckkart_aus_Worms_diesen_Taufstein._01.jpg', 'Master Eckart from Worms made this font in 1279. Apart from the building itself, it is the oldest piece on our walk.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('hs4nuryjuw', 'daily:wuerzburg-dom:1706-giovanni-pietro-magni-stucco-ceiling-of-the-crossing', 'Stucco ceiling of the crossing', 'Giovanni Pietro Magni', 1706, '1701–1706', 'Baroque', 'stucco', 'Würzburg Cathedral (Kiliansdom)', 3, 'architecture', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Stuccoed_ceiling_%28crossing%29_-_St._Kilian%27s_Cathedral_-_W%C3%BCrzburg_-_Germany_2017.jpg/1280px-Stuccoed_ceiling_%28crossing%29_-_St._Kilian%27s_Cathedral_-_W%C3%BCrzburg_-_Germany_2017.jpg', 'Giovanni Pietro Magni and a team of stucco workers from Ticino covered the Romanesque church in baroque decoration between 1701 and 1706. The walls underneath are more than six hundred years older.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('smb836nzqh', 'daily:wuerzburg-dom:1420-unknown-master-piet', 'Pietà', 'Unknown master', 1420, 'around 1410–1420 (sources differ)', 'International Gothic', null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/2022_Kiliansdom_Skulptur_Pieta.jpg/1280px-2022_Kiliansdom_Skulptur_Pieta.jpg', 'Mary holds her dead son on her lap. The sources date this Pietà to around 1410 to 1420 and name no sculptor.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('u8kyytsg6y', 'daily:wuerzburg-dom:1967-otto-sonnleitner-kilian-portal', 'Kilian Portal', 'Otto Sonnleitner', 1967, null, null, 'portal', 'Würzburg Cathedral (Kiliansdom)', 3, 'architecture', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/W%C3%BCrzburg%2C_St.-Kilians-Dom_--_2018_--_0202.jpg/1280px-W%C3%BCrzburg%2C_St.-Kilians-Dom_--_2018_--_0202.jpg', 'Otto Sonnleitner made this portal in 1967, the year the rebuilt cathedral was consecrated again. Since then the church has been dedicated to Kilian and his companions.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('esdap5vn63', 'daily:wuerzburg-dom:1736-balthasar-neumann-sch-nborn-chapel', 'Schönborn Chapel', 'Balthasar Neumann', 1736, '1721–1736', 'Baroque', null, 'Würzburg Cathedral (Kiliansdom)', 2, 'architecture', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/W%C3%BCrzburg%2C_die_Sch%C3%B6nbornkapelle.JPG/1280px-W%C3%BCrzburg%2C_die_Sch%C3%B6nbornkapelle.JPG', 'Balthasar Neumann began the burial chapel of the Schönborn family in 1721. The shell stood by 1724, and the chapel was finished in 1736.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7acmeaj58r', 'daily:wuerzburg-dom:1075-bishops-bruno-and-adalbero-w-rzburg-cathedral', 'Würzburg Cathedral', 'Bishops Bruno and Adalbero', 1075, 'built 1040–1075', null, 'building', 'Würzburg Cathedral (Kiliansdom)', 2, 'architecture', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Fassade_W%C3%BCrzburger_Dom.jpg/1280px-Fassade_W%C3%BCrzburger_Dom.jpg', 'Bishop Bruno started the church in 1040, and it was finished under Bishop Adalbero in 1075. Two older cathedrals had stood here before it, and both were damaged by fire.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-07', 'wuerzburg-dom', 'One cathedral, many centuries', 'Ein Dom, viele Jahrhunderte', 'Today we walk through Würzburg Cathedral. Nearly a thousand years of art stand side by side in it, from the Middle Ages to after the war. We start at the pulpit and walk down the middle of the nave towards a tall candelabrum.', 'Heute gehen wir durch den Würzburger Dom. Darin stehen fast tausend Jahre Kunst nebeneinander, vom Mittelalter bis nach dem Krieg. Wir beginnen an der Kanzel und gehen durch die Mitte des Langhauses auf einen hohen Leuchter zu.', 'On 16 March 1945 bombs and fire hit the cathedral, and in February 1946 its north wall collapsed. The rebuilt church was consecrated again on 6 May 1967. That is why old and new art stand so close together here today.', 'Am 16. März 1945 trafen Bomben und Feuer den Dom, und im Februar 1946 stürzte seine Nordwand ein. Am 6. Mai 1967 wurde die wiederaufgebaute Kirche neu geweiht. Deshalb stehen alte und neue Kunst hier heute so dicht beieinander.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 0, 'f8d8bwnmba', null, null, 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 1, 'unmv9rqja6', 'The menorah is the newest piece on our walk. Now walk along the pillars on the left, where the prince-bishops keep watch.', 'Der Leuchter ist das jüngste Stück auf unserem Weg. Geh jetzt an den Pfeilern links entlang, wo die Fürstbischöfe Wache halten.', 'Photo: José Luiz, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 2, '2hat3rgzjg', 'Riemenschneider lived and worked in Würzburg, and he is buried in the city too. A few pillars on, a soldier waits.', 'Riemenschneider lebte und arbeitete in Würzburg und ist auch hier begraben. Ein paar Pfeiler weiter wartet ein Soldat.', 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 3, '38up9vv29h', 'It was probably carved by Michael Kern, from the same family of sculptors as the pulpit. Now head to the oldest treasure in the church.', 'Vermutlich stammt es von Michael Kern, aus derselben Bildhauerfamilie wie die Kanzel. Jetzt geht es zum ältesten Schatz der Kirche.', 'Photo: Nilaxus, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 4, 'd8dw8kcehs', 'From the oldest piece we look straight up, to the white ceiling over the crossing.', 'Vom ältesten Stück schauen wir direkt nach oben, zur weißen Decke über der Vierung.', 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 5, 'hs4nuryjuw', 'Below all that white and gold sits a quiet figure of grief, far older than the stucco.', 'Unter all dem Weiß und Gold sitzt eine stille Figur der Trauer, viel älter als der Stuck.', 'Photo: José Luiz, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 6, 'smb836nzqh', 'Now we step outside for a moment, to the side door on Kiliansplatz.', 'Jetzt gehen wir kurz hinaus, zum Seitenportal am Kiliansplatz.', 'Photo: Klaus Bärwinkel, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 7, 'u8kyytsg6y', 'Back inside, the north transept leads into a chapel built for one powerful family.', 'Zurück drinnen führt das nördliche Querhaus in eine Kapelle, die für eine mächtige Familie gebaut wurde.', 'Photo: Dietmar Rabich, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 8, 'esdap5vn63', 'Through the chapel we leave the cathedral. Turn around one last time and look at the whole church.', 'Durch die Kapelle verlassen wir den Dom. Dreh dich ein letztes Mal um und schau dir die ganze Kirche an.', 'Photo: Dguendel, CC BY 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 9, '7acmeaj58r', 'And that is the end of our walk.', 'Damit endet unser Rundgang.', 'Photo: Imaschke, CC BY-SA 4.0');
